CREATE TRIGGER st_own_ad AFTER DELETE ON st_own BEGIN UPDATE st_retained_stats SET n=n-1,bytes=bytes-length(old.row) WHERE kind='own'; END;
CREATE TRIGGER st_own_ai AFTER INSERT ON st_own BEGIN UPDATE st_retained_stats SET n=n+1,bytes=bytes+length(new.row) WHERE kind='own'; END;
CREATE TRIGGER st_own_au AFTER UPDATE ON st_own BEGIN UPDATE st_retained_stats SET bytes=bytes+length(new.row)-length(old.row) WHERE kind='own'; END;
CREATE TRIGGER st_tail_ad AFTER DELETE ON st_tail BEGIN UPDATE st_retained_stats SET n=n-1,bytes=bytes-length(old.item) WHERE kind='tail'; END;
CREATE TRIGGER st_tail_ai AFTER INSERT ON st_tail BEGIN UPDATE st_retained_stats SET n=n+1,bytes=bytes+length(new.item) WHERE kind='tail'; END;
CREATE TRIGGER st_tail_au AFTER UPDATE ON st_tail BEGIN UPDATE st_retained_stats SET bytes=bytes+length(new.item)-length(old.item) WHERE kind='tail'; END;
